async function connect(code:string,fresh=false,retries=0){const request=roomRequest.current;roomRef.current=code;setConnection('Connecting');let ticket='';if(import.meta.env.PROD&&!cloudHost){try{ticket=(await api('socket-ticket',{code})).ticket;}catch(e){setConnection('Connection failed');finishMatchmaking();setOnline(false);setError((e as Error).message);return;}}if(request!==roomRequest.current)return;const endpoint=import.meta.env.PROD&&!cloudHost?ONLINE_ORIGIN.replace('https:','wss:'):`${location.protocol==='https:'?'wss':'ws'}://${location.host}`;const socket=new RoomConnection(`${endpoint}/socket?code=${code}&device=${encodeURIComponent(deviceID())}${ticket?'&ticket='+encodeURIComponent(ticket):''}`,api,code);ws.current=socket;let firstSnapshot=true;setConnection('Connecting');socket.onopen=()=>{if(ws.current===socket)setConnection(import.meta.env.PROD?'Connected':'Connected · local dev');};socket.onmessage=e=>{if(ws.current!==socket)return;const d=JSON.parse(e.data);if(d.type==='state'){if(firstSnapshot){setError('');finishMatchmaking();setHydratedTable(!fresh&&!!d.started);firstSnapshot=false;setPresentationEpoch(e=>e+1);pending.current=null;setSubmitting(false);}setCasualTable(!!d.casual);setAutoPlay(!!d.autoPlay);setRemote(old=>old&&old.matchId===d.view.matchId&&old.revision>d.view.revision?old:d.view);setReadyAt(d.readyAt||0);setDeadline(d.deadline||0);setRemaining(Math.max(0,Math.ceil(((d.deadline||0)-(d.serverNow||Date.now()))/1000)));setTurnDuration(d.duration||20000);serverOffset.current=(d.serverNow||Date.now())-Date.now();setSeat(d.seat);setStarted(d.started);setHostSeat(d.hostSeat??0);setBotSeats(d.bots||[false,false,false,false]);setContinueBot(!!d.continueWithBot);setWaitingPartner(!!d.waitingForPartnerDecision);setSeatAvatars((d.avatars||[1,2,3,4]).map((id:number,i:number)=>d.bots?.[i]&&!d.rosterIds?.[i]?botAvatarFor(d.names[i],d.code):id));setSeatPhotos(d.photoURLs||[null,null,null,null]);setIdentities(d.names.map((n:string,i:number)=>i===d.seat?'You':n.replace(/ · Bot$/, '')));seq.current=d.seq;setRoom(d.code);setScreen('table');}if(d.type==='notice'&&typeof d.text==='string'&&typeof d.id==='string')setTableNotice({id:d.id,text:d.text});if(d.type==='session-replaced'){sessionReplaced();return;}if(d.type==='closed'){leave(false);setError(d.reason||'Table closed');}if(d.type==='ack'){setSelected('');}if(d.type==='error'){const rejected=pending.current?.card;pending.current=null;setSubmitting(false);if(rejected)setSelected(rejected);setError(d.message);}if(d.type==='emote'){showReaction(d.seat,d.text);}};socket.onclose=()=>{if(ws.current===socket){setConnection('Disconnected');if(firstSnapshot&&retries<2){setConnection('Retrying table connection…');window.setTimeout(()=>{if(ws.current===socket)void connect(code,fresh,retries+1).catch(e=>{finishMatchmaking();setOnline(false);setError((e as Error).message||'Unable to connect to the table.');});},700*(retries+1));}else if(firstSnapshot){setError('');finishMatchmaking();setOnline(false);setError(current=>current||'Unable to reach the table server. Please retry.');}else finishMatchmaking();}};}
async function joinFriendsTable(code:string){const active=await api('device-session',{action:'resume'});if(active.room!==code)throw Error('That invitation is no longer connected to your seat.');if(online&&room===code&&ws.current?.readyState===1)return;setFriendsOpen(false);setInspectedSeat(null);await resumeTable(code);}
async function resumeTable(code:string){roomRequest.current++;ws.current?.close();ws.current=null;pendingTable.current=view(createMatch(mode),0);setStarted(false);setOnline(true);setRemote(null);setGame(null);setAdvanced(null);setTutorial(-1);setRoom(code);setConnection('Returning to your table…');setScreen('table');await connect(code,false);}
async function refreshCloud(){if(!configured)return;try{applyCloud(await accountProfile());}catch(e){setError((e as Error).message);}}async function multiplayer(action:'create'|'join'|'quick',selectedMode=mode){if(matchmakingLock.current)return;matchmakingLock.current=true;const request=++roomRequest.current;roomAction.current={action,mode:selectedMode};setMatchmakingBusy(true);setError('');if(action!=='join'&&selectedMode==='band'&&!bandUnlocked){finishMatchmaking();setError('Band Rung is coming soon.');return;}if(import.meta.env.PROD&&!configured){finishMatchmaking();setError('Online tables are being configured. Choose Practice to play now.');return;}pendingTable.current=view(createMatch(selectedMode),0);setStarted(false);setCasualTable(action==='quick');setBotSeats([false,true,true,true]);setSeat(0);setHostSeat(0);setSeatPhotos([null,null,null,null]);setOnline(true);setRemote(null);setGame(null);setAdvanced(null);setTutorial(-1);setRoom('');setConnection(action==='quick'?'Finding your table…':'Creating your table…');setScreen('table');try{await api('session',configured?await secureSession():{});if(request!==roomRequest.current)return;const d=await api(action==='join'?'join':action==='quick'&&configured?'quick':'rooms',action==='join'?{code:join,avatar}:{mode:selectedMode,quick:action==='quick',avatar});if(request!==roomRequest.current)return;setRoom(d.code);void connect(d.code,action!=='join').catch(e=>{finishMatchmaking();setOnline(false);setError((e as Error).message||'Unable to connect to the table.');});}catch(e){if(request!==roomRequest.current)return;finishMatchmaking();setOnline(false);setError((import.meta.env.PROD?'Online connection failed. Please retry. ':'Local multiplayer server unavailable. Run npm run server. ')+(e as Error).message);}}
function leave(notify=true){roomRequest.current++;pendingTable.current=null;finishMatchmaking();if(notify&&online&&ws.current?.readyState===1)ws.current.send(JSON.stringify({type:'leave'}));setContinueBot(false);setWaitingPartner(false);pending.current=null;setSubmitting(false);ws.current?.close();ws.current=null;setOnline(false);setRemote(null);setGame(null);setAdvanced(null);setTutorial(-1);setScreen('lobby');setError('');setEmotesOpen(false);setSelected('');}
function card(c:Card,small=false){return <span className={'card-face'+(small?' small':'')}><img src={art('house/cards/'+rank(c.rank)+c.suit+'.webp')} alt="" draggable={false}/></span>;}
function showReaction(player:number,text:string){const id=Date.now();setChat({seat:player,text,id});timers.current.push(setTimeout(()=>setChat(current=>current?.id===id?null:current),2800));}
function seatDetails(player:number){if(online&&!started)return null;return <>{rolesReady&&player===(v?.dealer??rightOf(v!.caller))&&<b className="role-coin dealer-coin" title="Dealer seat">D</b>}{rolesReady&&player===v?.caller&&<b className="role-coin caller-coin" title="Rung caller">R</b>}{player===v?.senior&&<b key={'senior:'+v.history.length} className="role-coin senior-coin" title="Senior">S</b>}{reactionsAllowed&&chat?.seat===player&&<span key={chat.id} className="seat-reaction" role="status"><Reaction text={chat.text}/><span>{chat.text}</span></span>}</>;}
