useEffect(()=>{if(!reactionsAllowed){setEmotesOpen(false);setChat(null);}},[reactionsAllowed]);
useEffect(()=>{if(!reactionCooling)return;const timer=setTimeout(()=>setReactionCooling(false),5000);return()=>clearTimeout(timer);},[reactionCooling]);
function sendReaction(text:string){if(!reactionsAllowed||Date.now()-lastReactionSent.current<5000)return;lastReactionSent.current=Date.now();setReactionCooling(true);if(online)ws.current?.send(JSON.stringify({type:'emote',text}));else{showReaction(seat,text);}setEmotesOpen(false);}
